// =============================================================================
// FLILINK — Build + serve the production app over HTTPS for phone testing
// (npm run phone). Rebuild with the same command after code changes.
// =============================================================================

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import { createRequire } from 'node:module';

// Types generated by `next dev` can point at pages that no longer exist and
// fail the production type check — they are regenerated anyway
fs.rmSync('.next/dev/types', { recursive: true, force: true });

const nextBin = createRequire(import.meta.url).resolve('next/dist/bin/next');
const build = spawnSync(process.execPath, [nextBin, 'build'], { stdio: 'inherit' });
if (build.status !== 0) process.exit(build.status ?? 1);

await import('./serve-phone.mjs');
